"use client"

import * as React from "react"
import { CheckIcon, ChevronDownIcon, ShareIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Kbd } from "@/components/ui/kbd"
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"

import { ChatSidebar } from "./chat-sidebar"
import { CommandMenu } from "./command-menu"
import { Composer } from "./composer"
import { Conversation } from "./conversation"
import { models, replies, threads as seedThreads, user } from "./data"
import { ModelLogo } from "./logos"
import type { Attachment, Thread, Turn } from "./types"

const THINK_DELAY = 900
const TOKEN_DELAY = 40

export default function AgentWorkspace01() {
  const [threads, setThreads] = React.useState<Thread[]>(seedThreads)
  const [activeId, setActiveId] = React.useState<string | null>("heat-pump")
  const [draft, setDraft] = React.useState("")
  const [attachment, setAttachment] = React.useState<Attachment | null>(null)
  const [model, setModel] = React.useState(models[0]!.name)
  const [search, setSearch] = React.useState(false)
  const [editing, setEditing] = React.useState<{
    id: string
    text: string
  } | null>(null)
  const replyIndexRef = React.useRef(0)
  const timerRef = React.useRef<number | null>(null)

  const thread = threads.find((t) => t.id === activeId) ?? null
  const streaming = thread?.turns.some((t) => t.streaming) ?? false
  const altModel = models.find((m) => m.name !== model)?.name ?? model

  React.useEffect(
    () => () => {
      if (timerRef.current) window.clearTimeout(timerRef.current)
    },
    []
  )

  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault()
        setSearch(true)
      }
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [])

  const patch = (threadId: string, turnId: string, fn: (t: Turn) => Turn) =>
    setThreads((prev) =>
      prev.map((t) =>
        t.id === threadId
          ? { ...t, turns: t.turns.map((m) => (m.id === turnId ? fn(m) : m)) }
          : t
      )
    )

  const clearTimer = () => {
    if (timerRef.current) {
      window.clearTimeout(timerRef.current)
      timerRef.current = null
    }
  }

  const stream = (threadId: string, turnId: string) => {
    clearTimer()
    const reply = replies[replyIndexRef.current % replies.length]!
    replyIndexRef.current += 1

    patch(threadId, turnId, (t) => ({
      ...t,
      text: "",
      reasoning: reply.reasoning,
      thought: undefined,
      error: undefined,
      streaming: true,
    }))

    let shown = 0
    const tick = () => {
      shown = Math.min(
        reply.text.length,
        shown + 2 + Math.floor(Math.random() * 5)
      )
      const done = shown >= reply.text.length
      patch(threadId, turnId, (t) => ({
        ...t,
        text: reply.text.slice(0, shown),
        thought: done
          ? 4 + Math.round(reply.reasoning.length / 40)
          : t.thought,
        streaming: !done,
      }))
      timerRef.current = done
        ? null
        : window.setTimeout(tick, TOKEN_DELAY * (0.5 + Math.random()))
    }
    tick()
  }

  const stop = () => {
    clearTimer()
    const live = thread?.turns.find((t) => t.streaming)
    if (thread && live) {
      patch(thread.id, live.id, (t) => ({
        ...t,
        streaming: false,
        error: true,
      }))
    }
  }

  const send = () => {
    const text = draft.trim()
    if ((!text && !attachment) || streaming) return

    const body = text || `Shared ${attachment?.name ?? "attachment"}`
    const replyId = crypto.randomUUID()
    const turns: Turn[] = [
      { id: crypto.randomUUID(), role: "user", text: body, day: "today" },
      {
        id: replyId,
        role: "assistant",
        text: "",
        streaming: true,
        day: "today",
      },
    ]
    const id = thread?.id ?? crypto.randomUUID()

    setThreads((prev) =>
      thread
        ? [
            {
              ...thread,
              updated: "now",
              group: "today",
              turns: [
                ...thread.turns.map((t) => ({
                  ...t,
                  day: t.day ?? thread.group,
                })),
                ...turns,
              ],
            },
            ...prev.filter((t) => t.id !== id),
          ]
        : [
            {
              id,
              title: body.split(" ").slice(0, 5).join(" ") || "New chat",
              preview: body,
              updated: "now",
              group: "today",
              turns,
            },
            ...prev,
          ]
    )
    setActiveId(id)
    setDraft("")
    setAttachment(null)
    setEditing(null)
    window.setTimeout(() => stream(id, replyId), THINK_DELAY)
  }

  const retry = (turnId: string, next?: string) => {
    if (!thread) return
    if (next) setModel(next)
    patch(thread.id, turnId, (t) => ({
      ...t,
      text: "",
      thought: undefined,
      error: undefined,
      streaming: true,
    }))
    window.setTimeout(() => stream(thread.id, turnId), THINK_DELAY)
  }

  const startEdit = (turn: Turn) => {
    if (streaming || turn.role !== "user") return
    setEditing({ id: turn.id, text: turn.text })
  }

  const cancelEdit = () => setEditing(null)

  const commitEdit = () => {
    if (!thread || !editing || streaming) return
    const text = editing.text.trim()
    if (!text) return

    const at = thread.turns.findIndex((t) => t.id === editing.id)
    if (at < 0) return

    const replyId = crypto.randomUUID()
    setThreads((prev) =>
      prev.map((t) =>
        t.id !== thread.id
          ? t
          : {
              ...t,
              updated: "now",
              preview: text,
              turns: [
                ...t.turns.slice(0, at),
                { ...t.turns[at]!, text },
                {
                  id: replyId,
                  role: "assistant",
                  text: "",
                  streaming: true,
                  day: "today",
                },
              ],
            }
      )
    )
    setEditing(null)
    window.setTimeout(() => stream(thread.id, replyId), THINK_DELAY)
  }

  const activeModel = models.find((m) => m.name === model) ?? models[0]!

  return (
    <SidebarProvider
      className="h-full max-h-full min-h-0!"
      style={{ "--sidebar-width": "260px" } as React.CSSProperties}
    >
      <ChatSidebar
        activeId={activeId}
        onChange={(next) => {
          setThreads(next)
          if (activeId && !next.some((t) => t.id === activeId)) {
            setActiveId(null)
            setEditing(null)
          }
        }}
        onNew={() => {
          setActiveId(null)
          setEditing(null)
        }}
        onSearch={() => setSearch(true)}
        onSelect={(id) => {
          setActiveId(id)
          setEditing(null)
        }}
        threads={threads}
        user={user}
      />

      <SidebarInset className="min-h-0 overflow-hidden bg-white dark:bg-background">
        <header className="flex h-13 shrink-0 items-center gap-2.5 border-b border-border/70 bg-white px-4 dark:bg-background">
          <SidebarTrigger className="size-7.5 rounded-lg text-muted-foreground" />

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                type="button"
                variant="secondary"
                className="h-8 gap-1.5 rounded-lg px-2.5 text-[13px]"
              >
                <ModelLogo
                  className="size-3.5"
                  vendor={activeModel.vendor}
                />
                {model}
                <ChevronDownIcon
                  className="size-3 text-muted-foreground"
                  aria-hidden
                />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="start"
              sideOffset={6}
              className="w-75 rounded-xl p-1.5"
            >
              <DropdownMenuGroup className="flex flex-col gap-0.5">
                {models.map((m) => (
                  <DropdownMenuItem
                    key={m.name}
                    className={cn(
                      "gap-2.5 rounded-md px-2.5 py-2",
                      m.name === model && "bg-muted"
                    )}
                    onClick={() => setModel(m.name)}
                  >
                    <span className="flex grow flex-col gap-0.5">
                      <span className="flex items-center gap-1.5 text-[13px]/4 font-medium">
                        <ModelLogo
                          className="size-3 shrink-0"
                          vendor={m.vendor}
                        />
                        {m.name}
                      </span>
                      <span className="text-[11px]/3.5 text-muted-foreground">
                        {m.hint}
                      </span>
                    </span>
                    {m.name === model ? (
                      <CheckIcon className="size-3.5" aria-hidden />
                    ) : null}
                    <Kbd className="h-4.5 border border-border bg-background px-1.5 font-mono text-[10px]">
                      {m.context}
                    </Kbd>
                  </DropdownMenuItem>
                ))}
              </DropdownMenuGroup>
            </DropdownMenuContent>
          </DropdownMenu>

          <div className="grow" />

          {thread ? (
            <Button
              type="button"
              aria-label="Share thread"
              className="size-7.5 rounded-lg text-muted-foreground"
              size="icon-sm"
              variant="ghost"
            >
              <ShareIcon className="size-4" aria-hidden />
            </Button>
          ) : null}
        </header>

        <Conversation
          altModel={altModel}
          editing={editing}
          onCancelEdit={cancelEdit}
          onCommitEdit={commitEdit}
          onEdit={startEdit}
          onEditingChange={(text) =>
            setEditing((cur) => (cur ? { ...cur, text } : cur))
          }
          onOpen={setActiveId}
          onRetry={retry}
          recent={threads.filter((t) => !t.pinned).slice(0, 3)}
          thread={thread}
        />

        <Composer
          attachment={attachment}
          draft={draft}
          onAttachment={setAttachment}
          onDraft={setDraft}
          onSend={send}
          onStop={stop}
          streaming={streaming}
        />
      </SidebarInset>

      <CommandMenu
        onNew={(text) => {
          setActiveId(null)
          setDraft(text)
        }}
        onOpen={setActiveId}
        onOpenChange={setSearch}
        open={search}
        threads={threads}
      />
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"
import { MessageSquareIcon, PlusIcon } from "lucide-react"

import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"

import type { Thread } from "./types"

export function CommandMenu({
  open,
  onOpenChange,
  threads,
  onOpen,
  onNew,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  threads: Thread[]
  onOpen: (id: string) => void
  onNew: (text: string) => void
}) {
  return (
    <CommandDialog open={open} onOpenChange={onOpenChange}>
      <Command>
        <CommandInput placeholder="Search chats or start a prompt..." />
        <CommandList>
          <CommandEmpty>No chats found.</CommandEmpty>
          <CommandGroup heading="Actions">
            <CommandItem
              value="new-chat"
              onSelect={() => {
                onNew("")
                onOpenChange(false)
              }}
            >
              <PlusIcon className="size-4" aria-hidden />
              New chat
            </CommandItem>
          </CommandGroup>
          <CommandGroup heading="Recent">
            {threads.map((thread) => (
              <CommandItem
                key={thread.id}
                value={`${thread.title} ${thread.preview}`}
                onSelect={() => {
                  onOpen(thread.id)
                  onOpenChange(false)
                }}
              >
                <MessageSquareIcon className="size-4" aria-hidden />
                <span className="truncate">{thread.title}</span>
              </CommandItem>
            ))}
          </CommandGroup>
        </CommandList>
      </Command>
    </CommandDialog>
  )
}

"use client"

import * as React from "react"
import {
  CheckIcon,
  CopyIcon,
  PencilIcon,
  RefreshCwIcon,
  ThumbsDownIcon,
  ThumbsUpIcon,
  TriangleAlertIcon,
} from "lucide-react"

import { Bubble, BubbleContent } from "@/components/ui/bubble"
import { Button } from "@/components/ui/button"
import {
  Message,
  MessageContent,
  MessageFooter,
} from "@/components/ui/message"
import { Textarea } from "@/components/ui/textarea"
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/components/ui/message-scroller"
import { cn } from "@/lib/utils"

import type { Thread, Turn } from "./types"

const easeOut = "ease-[cubic-bezier(0.23,1,0.32,1)]"
const press = `${easeOut} transition-[scale,background-color,color] duration-150 active:scale-[0.96]`
const enter = `${easeOut} motion-reduce:slide-in-from-bottom-0 fade-in slide-in-from-bottom-1 animate-in duration-200`
const swap = `${easeOut} fade-in zoom-in-95 animate-in duration-150`

const actionBtn =
  "size-8 rounded-md text-muted-foreground hover:bg-muted/50 hover:text-foreground"

export function Conversation({
  thread,
  recent,
  altModel,
  editing,
  onEdit,
  onEditingChange,
  onCancelEdit,
  onCommitEdit,
  onRetry,
  onOpen,
}: {
  thread: Thread | null
  recent: Thread[]
  altModel: string
  editing: { id: string; text: string } | null
  onEdit: (turn: Turn) => void
  onEditingChange: (text: string) => void
  onCancelEdit: () => void
  onCommitEdit: () => void
  onRetry: (turnId: string, nextModel?: string) => void
  onOpen: (id: string) => void
}) {
  const [copiedId, setCopiedId] = React.useState<string | null>(null)
  const [votes, setVotes] = React.useState<Record<string, "up" | "down">>({})
  const copyTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  const editAreaRef = React.useRef<HTMLTextAreaElement>(null)

  React.useLayoutEffect(() => {
    if (!editing) return
    const el = editAreaRef.current
    if (!el) return
    el.focus()
    const n = el.value.length
    el.setSelectionRange(n, n)
  }, [editing?.id])

  React.useEffect(
    () => () => {
      if (copyTimerRef.current) clearTimeout(copyTimerRef.current)
    },
    []
  )

  const copyText = async (id: string, text: string) => {
    try {
      await navigator.clipboard.writeText(text)
      setCopiedId(id)
      if (copyTimerRef.current) clearTimeout(copyTimerRef.current)
      copyTimerRef.current = setTimeout(() => {
        setCopiedId((cur) => (cur === id ? null : cur))
        copyTimerRef.current = null
      }, 1800)
    } catch {
      // Clipboard may be denied in embeds; ignore.
    }
  }

  const vote = (id: string, next: "up" | "down") => {
    setVotes((prev) => {
      if (prev[id] === next) {
        const { [id]: _removed, ...rest } = prev
        return rest
      }
      return { ...prev, [id]: next }
    })
  }

  if (!thread) {
    return (
      <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-6 bg-white px-6 dark:bg-background">
        <div className="max-w-md text-center">
          <h2 className="text-xl font-semibold tracking-tight">
            Start a workspace chat
          </h2>
          <p className="mt-2 text-sm text-muted-foreground">
            Ask anything, attach a file, or reopen a recent thread from the
            sidebar.
          </p>
        </div>
        {recent.length > 0 ? (
          <ul className="flex w-full max-w-md flex-col gap-1">
            {recent.map((item) => (
              <li key={item.id}>
                <button
                  type="button"
                  onClick={() => onOpen(item.id)}
                  className="flex w-full cursor-pointer items-center rounded-lg px-3 py-2 text-start text-sm transition-colors hover:bg-muted"
                >
                  <span className="truncate">{item.title}</span>
                </button>
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    )
  }

  const streaming = thread.turns.some((turn) => turn.streaming)

  return (
    <MessageScrollerProvider
      key={thread.id}
      autoScroll={streaming}
      defaultScrollPosition="end"
    >
      <MessageScroller className="min-h-0 flex-1 bg-white dark:bg-background">
        <MessageScrollerViewport>
          <MessageScrollerContent className="mx-auto w-full max-w-2xl justify-end gap-4 px-4 pt-8 pb-4">
            {thread.turns.map((turn) => {
              const mine = turn.role === "user"
              const align = mine ? "end" : "start"
              return (
                <MessageScrollerItem
                  key={turn.id}
                  messageId={turn.id}
                  scrollAnchor={mine}
                  className={cn(mine && "pt-4 first:pt-0", enter)}
                >
                  <Message align={align}>
                    <MessageContent className="gap-2">
                      {editing?.id === turn.id ? (
                        <>
                          <Textarea
                            ref={editAreaRef}
                            aria-label="Edit message"
                            className={cn(
                              enter,
                              "min-h-0 w-md max-w-full resize-none rounded-[18px] border border-border/70 bg-white px-3.5 py-2.5 text-[15px]/6 shadow-xs focus-visible:ring-0 dark:bg-card md:text-[15px]/6"
                            )}
                            value={editing.text}
                            onChange={(e) => onEditingChange(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === "Escape") onCancelEdit()
                              if (e.key === "Enter" && !e.shiftKey) {
                                e.preventDefault()
                                onCommitEdit()
                              }
                            }}
                          />
                          <div
                            className={cn(
                              enter,
                              "flex items-center gap-1.5 self-end"
                            )}
                          >
                            <Button
                              type="button"
                              className={cn(press, "rounded-full")}
                              onClick={onCancelEdit}
                              size="sm"
                              variant="secondary"
                            >
                              Cancel
                            </Button>
                            <Button
                              type="button"
                              className={cn(press, "rounded-full")}
                              disabled={!editing.text.trim() || streaming}
                              onClick={onCommitEdit}
                              size="sm"
                            >
                              Send
                            </Button>
                          </div>
                        </>
                      ) : turn.streaming && !turn.text ? (
                        <span className="shimmer text-[15px]/6 text-muted-foreground">
                          Thinking...
                        </span>
                      ) : (
                        turn.text.split("\n\n").map((paragraph, i) => (
                          <Bubble
                            key={`${turn.id}-${i}`}
                            align={align}
                            variant={mine ? "muted" : "ghost"}
                            className="max-w-md data-[variant=ghost]:max-w-full"
                          >
                            <BubbleContent className="rounded-[18px] px-3.5 py-2 text-[15px]/6">
                              {paragraph}
                            </BubbleContent>
                          </Bubble>
                        ))
                      )}

                      {!mine &&
                      turn.reasoning &&
                      !turn.streaming &&
                      editing?.id !== turn.id ? (
                        <p className="max-w-md text-xs text-muted-foreground">
                          Thought for {turn.thought ?? 3}s · {turn.reasoning}
                        </p>
                      ) : null}

                      {turn.error && editing?.id !== turn.id ? (
                        <div className="flex max-w-md items-start gap-2 rounded-[12px] border border-destructive/30 bg-destructive/5 px-3 py-2 text-xs text-destructive">
                          <TriangleAlertIcon
                            className="mt-0.5 size-3.5 shrink-0"
                            aria-hidden
                          />
                          <div className="flex flex-col gap-1.5">
                            <span>Generation stopped.</span>
                            <div className="flex flex-wrap gap-1.5">
                              <Button
                                type="button"
                                size="xs"
                                variant="outline"
                                className="h-7 rounded-full"
                                onClick={() => onRetry(turn.id)}
                              >
                                Retry
                              </Button>
                              <Button
                                type="button"
                                size="xs"
                                variant="ghost"
                                className="h-7 rounded-full"
                                onClick={() => onRetry(turn.id, altModel)}
                              >
                                Try {altModel}
                              </Button>
                            </div>
                          </div>
                        </div>
                      ) : null}

                      {turn.text &&
                      !turn.streaming &&
                      editing?.id !== turn.id ? (
                        <MessageFooter className="-mx-2 gap-0.5">
                          <Button
                            type="button"
                            aria-label={
                              copiedId === turn.id ? "Copied" : "Copy"
                            }
                            aria-pressed={copiedId === turn.id}
                            size="icon-sm"
                            variant="ghost"
                            className={cn(
                              press,
                              actionBtn,
                              copiedId === turn.id && "text-foreground"
                            )}
                            onClick={() => copyText(turn.id, turn.text)}
                          >
                            {copiedId === turn.id ? (
                              <CheckIcon
                                className={cn(swap, "size-4")}
                                aria-hidden
                              />
                            ) : (
                              <CopyIcon className="size-4" aria-hidden />
                            )}
                          </Button>
                          {mine ? (
                            <Button
                              type="button"
                              aria-label="Edit"
                              size="icon-sm"
                              variant="ghost"
                              className={cn(press, actionBtn)}
                              disabled={streaming}
                              onClick={() => onEdit(turn)}
                            >
                              <PencilIcon className="size-4" aria-hidden />
                            </Button>
                          ) : (
                            <>
                              <Button
                                type="button"
                                aria-label="Good response"
                                aria-pressed={votes[turn.id] === "up"}
                                size="icon-sm"
                                variant="ghost"
                                className={cn(
                                  press,
                                  actionBtn,
                                  votes[turn.id] === "up" && "text-foreground"
                                )}
                                onClick={() => vote(turn.id, "up")}
                              >
                                <ThumbsUpIcon
                                  className={cn(
                                    "size-4",
                                    votes[turn.id] === "up" && "fill-current"
                                  )}
                                  aria-hidden
                                />
                              </Button>
                              <Button
                                type="button"
                                aria-label="Bad response"
                                aria-pressed={votes[turn.id] === "down"}
                                size="icon-sm"
                                variant="ghost"
                                className={cn(
                                  press,
                                  actionBtn,
                                  votes[turn.id] === "down" && "text-foreground"
                                )}
                                onClick={() => vote(turn.id, "down")}
                              >
                                <ThumbsDownIcon
                                  className={cn(
                                    "size-4",
                                    votes[turn.id] === "down" && "fill-current"
                                  )}
                                  aria-hidden
                                />
                              </Button>
                              <Button
                                type="button"
                                aria-label="Regenerate"
                                size="icon-sm"
                                variant="ghost"
                                className={cn(press, actionBtn)}
                                onClick={() => onRetry(turn.id)}
                              >
                                <RefreshCwIcon
                                  className="size-4"
                                  aria-hidden
                                />
                              </Button>
                            </>
                          )}
                        </MessageFooter>
                      ) : null}
                    </MessageContent>
                  </Message>
                </MessageScrollerItem>
              )
            })}
          </MessageScrollerContent>
        </MessageScrollerViewport>
        <MessageScrollerButton className={easeOut} />
      </MessageScroller>
    </MessageScrollerProvider>
  )
}

import type { Model, StreamReply, Thread, WorkspaceUser } from "./types"

export const user: WorkspaceUser = {
  name: "Alex Rivera",
  email: "alex@example.com",
  initials: "AR",
}

export const models: Model[] = [
  {
